UPDATE knowledge_base k SET answer = r.answer, answer_en = r.answer_en, updated_at = r.updated_at FROM json_populate_record(null::knowledge_base, U&'{"id":"9e3465b9-4c1e-4f02-9fd6-8fe2fe00dd85","category":"prix","subcategory":"Pricing & Payments","property":"all","question":"Comment La Villa se compare-t-il \00E0 la location \00E0 Gen\00E8ve ?","answer":"Un studio \00E0 Gen\00E8ve co\00FBte g\00E9n\00E9ralement 1 500-2 500 CHF/mois, plus les charges (150-250 CHF), internet (50-80 CHF), abonnement de salle de sport (100-150 CHF), et vous devriez acheter des meubles. Chez La Villa, \00E0 partir de 1\00A0370 CHF, vous obtenez une chambre priv\00E9e meubl\00E9e, tous les services, internet, salle de sport, piscine, sauna, m\00E9nage et une communaut\00E9 int\00E9gr\00E9e. La valeur est exceptionnelle.","keywords":[],"priority":10,"active":true,"source_url":null,"created_at":"2026-02-19T06:50:02.906856+00:00","updated_at":"2026-02-19T06:50:02.906856+00:00","question_en":"How does La Villa compare to renting in Geneva?","answer_en":"A studio apartment in Geneva typically costs 1,500-2,500 CHF/month, plus utilities (150-250 CHF), internet (50-80 CHF), gym membership (100-150 CHF), and you''d need to buy furniture. At La Villa, starting from 1,370 CHF, you get a furnished private room, all utilities, internet, gym, pool, sauna, cleaning, and a built-in community. The value is exceptional.","slug":"price-comparison-geneva"}'::json) r WHERE k.id = '9e3465b9-4c1e-4f02-9fd6-8fe2fe00dd85'::uuid;
UPDATE knowledge_base k SET answer = r.answer, answer_en = r.answer_en, updated_at = r.updated_at FROM json_populate_record(null::knowledge_base, U&'{"id":"bc9c8ce7-bc0b-4234-bb67-739735fc6720","category":"prix","subcategory":null,"property":"all","question":"Quel est le prix d''une chambre ?","answer":"Nos chambres sont \00E0 1 430 CHF/mois, soit 1 530 \20AC, tout compris (La Villa avec salle d''eau partag\00E9e : 1 370 CHF / 1 470 \20AC). Inclus : charges, fibre, m\00E9nage des communs 3x/semaine, piscine, sauna, salle de sport, cours de sport et yoga mensuels dans chaque maison, Pizza Party mensuelle, abonnements streaming, linge de lit et serviettes, produits de base. Aucun frais d''entr\00E9e.","keywords":["prix","loyer","combien","tarif","co\00FBt","budget","mensuel"],"priority":1,"active":true,"source_url":null,"created_at":"2026-02-17T16:03:43.996243+00:00","updated_at":"2026-09-03T12:36:48.448522+00:00","question_en":null,"answer_en":"Our rooms are CHF 1,430/month, i.e. \20AC1,530, all inclusive (La Villa with shared bathroom: CHF 1,370 / \20AC1,470). Included: utilities, fibre internet, common-area cleaning 3x/week, pool, sauna, gym, monthly yoga and fitness sessions in each house, monthly Pizza Party, streaming subscriptions, bed linen and towels, basic supplies. No entry fees.","slug":null}'::json) r WHERE k.id = 'bc9c8ce7-bc0b-4234-bb67-739735fc6720'::uuid;
UPDATE knowledge_base k SET answer = r.answer, answer_en = r.answer_en, updated_at = r.updated_at FROM json_populate_record(null::knowledge_base, U&'{"id":"bca165a4-000f-4158-8dd7-d1460b5c53a9","category":"prix","subcategory":"Pricing & Payments","property":"all","question":"Combien co\00FBte la vie \00E0 La Villa ?","answer":"Nos tarifs sont de 1 370 CHF (1 470 \20AC) \00E0 1 430 CHF (1 530 \20AC) par mois selon la maison et le type de salle d''eau \2014 priv\00E9e ou partag\00E9e. C''est un tarif tout inclus, sans frais cach\00E9s ni frais d''entr\00E9e. Compar\00E9 \00E0 un studio \00E0 Gen\00E8ve avec les charges, l''internet, les meubles et la salle de sport, La Villa offre une valeur nettement sup\00E9rieure.","keywords":[],"priority":10,"active":true,"source_url":null,"created_at":"2026-02-19T06:50:02.906856+00:00","updated_at":"2026-09-03T12:36:48.448522+00:00","question_en":"How much does it cost to live at La Villa?","answer_en":"Our rates range from CHF 1,370 (\20AC1,470) to CHF 1,430 (\20AC1,530) per month depending on the house and bathroom type \2014 private or shared. It''s an all-inclusive rate with no hidden costs or entry fees. Compared with a Geneva studio plus utilities, internet, furniture and a gym membership, La Villa offers far better value.","slug":"monthly-cost"}'::json) r WHERE k.id = 'bca165a4-000f-4158-8dd7-d1460b5c53a9'::uuid;
UPDATE knowledge_base k SET answer = r.answer, answer_en = r.answer_en, updated_at = r.updated_at FROM json_populate_record(null::knowledge_base, U&'{"id":"c04f73b9-1aa5-4065-b247-1c8954bcc84b","category":"concept","subcategory":"Getting Started","property":"all","question":"Le coliving est-il cher ?","answer":"Quand vous prenez en compte tous les co\00FBts \2014 loyer, charges, internet, meubles, salle de sport, m\00E9nage et divertissement \2014 le coliving est souvent plus \00E9conomique que la location traditionnelle. Chez La Villa, nos tarifs tout inclus vont de 1 370 CHF (1 470 \20AC) \00E0 1 430 CHF (1 530 \20AC) par mois, ce qui est comp\00E9titif face \00E0 un studio \00E0 Gen\00E8ve une fois tout additionn\00E9.","keywords":[],"priority":10,"active":true,"source_url":null,"created_at":"2026-02-19T06:50:02.906856+00:00","updated_at":"2026-09-03T12:36:48.448522+00:00","question_en":"Is coliving expensive?","answer_en":"When you factor in all costs\2014rent, utilities, internet, furniture, gym membership, cleaning services, and entertainment\2014coliving is often more economical than traditional renting. At La Villa, our all-inclusive rates start from 1,370 CHF/month, which is competitive with Geneva studio prices while including: heated pool, gym, sauna, weekly yoga classes, parking, monthly Pizza Party, monthly community evenings, streaming subscriptions, and more.","slug":"is-coliving-expensive"}'::json) r WHERE k.id = 'c04f73b9-1aa5-4065-b247-1c8954bcc84b'::uuid;
